package com.bank.etl.job;

import com.bank.etl.model.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Classic ETL job: extract → transform (filter + enrich) → load (upsert).
public class EtlJob {
    private static final Logger log = Logger.getLogger(EtlJob.class.getName());

    private final Map<String, Account> accountRef;
    // Warehouse target keyed by txn id so an upsert is naturally idempotent.
    private final Map<String, EnrichedTransaction> warehouse = new LinkedHashMap<>();

    public EtlJob(Map<String, Account> accountRef) { this.accountRef = accountRef; }

    public List<SourceRow> extract() {
        log.info("EXTRACT: reading raw source transactions");
        return List.of(
            new SourceRow("TXN-1", "SAV2001", new BigDecimal("1200.00")),
            new SourceRow("TXN-2", "CUR3001", new BigDecimal("5000.00")),
            new SourceRow("TXN-3", "SAV2001", null) // invalid — must be dropped
        );
    }

    public List<EnrichedTransaction> transform(List<SourceRow> rows) {
        log.info("TRANSFORM: filtering invalid rows and enriching with holder name");
        List<EnrichedTransaction> out = new ArrayList<>();
        for (SourceRow r : rows) {
            if (r.getAmount() == null || r.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
                log.warning(() -> "Dropping invalid row " + r.getTxnId());
                continue;
            }
            Account acc = accountRef.get(r.getAccountId());
            String name = acc != null ? acc.getHolderName() : "UNKNOWN";
            out.add(new EnrichedTransaction(r.getTxnId(), r.getAccountId(), name, r.getAmount()));
        }
        return out;
    }

    public void load(List<EnrichedTransaction> enriched) {
        log.info("LOAD: upserting into warehouse (idempotent by txn id)");
        for (EnrichedTransaction e : enriched) {
            warehouse.put(e.getTxnId(), e); // put = insert or update → no duplicates
        }
    }

    public Map<String, EnrichedTransaction> getWarehouse() { return warehouse; }
}
