package com.bank.etl;

import com.bank.etl.job.EtlJob;
import com.bank.etl.model.*;
import java.util.*;
import java.util.logging.Logger;

public class EtlApplication {
    private static final Logger log = Logger.getLogger(EtlApplication.class.getName());

    public static void main(String[] args) {
        Map<String, Account> ref = Map.of(
            "SAV2001", new Account("SAV2001", "Rajesh Kumar"),
            "CUR3001", new Account("CUR3001", "Priya Sharma"));

        EtlJob job = new EtlJob(ref);

        // Run twice to prove idempotency — warehouse size must not grow.
        for (int run = 1; run <= 2; run++) {
            log.info("=== ETL RUN " + run + " ===");
            job.load(job.transform(job.extract()));
            log.info("Warehouse now holds " + job.getWarehouse().size() + " rows");
        }

        job.getWarehouse().values().forEach(e ->
            log.info(e.getTxnId() + " " + e.getHolderName() + " " + e.getAmount()));
    }
}
